import{z as o,x as B,o as i,c as D,q as s,j as n,D as E,d as a,s as d,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SCHED_DEADLINE","description":"","frontmatter":{"title":"SCHED_DEADLINE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sched-deadline.md","filePath":"cs/sched-deadline.md","lastUpdated":1791063341000}'),A={name:"cs/sched-deadline.md"};function c(p,e,C,m,h,u){const t=B("Mermaid");return i(),D("div",null,[e[2]||(e[2]=s('<h1 id="sched-deadline" tabindex="-1">SCHED_DEADLINE <a class="header-anchor" href="#sched-deadline" aria-label="Permalink to &quot;SCHED_DEADLINE&quot;">​</a></h1><div class="epigraph"><p>SCHED_DEADLINE 实现 CBS：任务申报运行时、周期与截止，内核保证在截止前给够预算，否则节流。</p><footer>—— 据 Linux sched-deadline 文档；Abeni 与 Buttazzo 对 CBS 的论述；POSIX sporatic server 直觉</footer></div><p><a href="/cs/eevdf">EEVDF</a> 是尽力公平。<a href="/cs/heterogeneous-core-sched">异构</a> 是容量。硬实时要 <strong>带宽隔离</strong>。缺口是 deadline 调度类：全局 EDF + CBS，不是用户写一个定时器循环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>sched_setattr</code>：runtime ≤ deadline ≤ period。准入：总和不超过 CPU 带宽（可留 5% 给其它）。运行：EDF 选最早截止，用尽 runtime 则节流到下周期。缺口：与 FIFO/RR 的优先级关系（DL 高于 RT 高于 CFS，通常）；fork 不继承；亲和与全局队列。本课不把 GEDF 可调度性证明展开成课程。<span class="marginnote">CBS 就是用「记账 + 罚坐」的手段来做「带宽隔离」的事：每个 DL 任务有一本自己的预算账，花超了不冻别人也不冻死自己，而是罚到下个周期再开工——多媒体回路不会再被失控进程拖垮，失控进程也只是自己卡顿。</span></p><p><span class="marginnote">错过截止会统计，不自动变 CFS。对象是 CPU 时间，不是磁盘 deadline 调度器。</span></p><p><span class="marginnote">数字实例：视频解码任务申报 runtime=5 ms、period=33 ms，占带宽 5/33≈15%；三个这样的任务合计 45%，仍低于约 95% 的准入线。少报 runtime 会在中途被节流（自己卡），多报则白白占用准入名额、挤掉别人的任务——申报越贴近真实负载，系统塞得越满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>准入会计 → 入 DL 队列。tick/hrtimer 扣 runtime。对照 <a href="/cs/blk-schedulers">blk mq-deadline</a>：名字像，对象不是 bio。对照 <a href="/cs/memcg">memcg</a>：一个限内存，一个限 CPU 时间形状。对照 EAS：DL 任务往往不参与省电迁移。</p>',9)),(i(),n(l,null,{default:E(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADM%5B%22%E5%B8%A6%E5%AE%BD%E5%87%86%E5%85%A5%22%5D%20--%3E%20RUN%5B%22EDF%20%E9%80%89%E6%9C%80%E6%97%A9%E6%88%AA%E6%AD%A2%22%5D%0A%20%20RUN%20--%3E%20BUD%5B%22%E6%B6%88%E8%80%97%20runtime%22%5D%0A%20%20BUD%20--%3E%7C%22%E8%80%97%E5%B0%BD%22%7C%20THR%5B%22%E8%8A%82%E6%B5%81%E5%88%B0%E4%B8%8B%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[a("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,[a("CBS 把「周期性工作」收成内核保证，使媒体与控制回路不必靠 nice。过载被准入挡住，而不是大家一起错过。不要写成航空认证。与 "),r("a",{href:"/cs/napi"},"NAPI"),a("：硬中断仍可拉延迟，后课 PREEMPT_RT。")],-1)),(i(),n(l,null,{default:E(()=>[d(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22t%3D0%EF%BC%9A%E4%BD%9C%E4%B8%9A%E9%87%8A%E6%94%BE%3Cbr%2F%3E%E9%A2%84%E7%AE%97%E8%A1%A5%E6%BB%A1%20runtime%22%5D%20--%3E%20TD%5B%22t%3Ddeadline%EF%BC%9A%3Cbr%2F%3EEDF%20%E5%85%A8%E5%B1%80%E6%AF%94%E8%BE%83%E7%9A%84%E7%BB%9D%E5%AF%B9%E6%AD%BB%E7%BA%BF%22%5D%0A%20%20TD%20--%3E%20TP%5B%22t%3Dperiod%EF%BC%9A%E4%B8%8B%E4%B8%80%E4%BB%BD%E4%BD%9C%E4%B8%9A%E9%87%8A%E6%94%BE%3Cbr%2F%3E%E8%8A%82%E6%B5%81%E4%B8%AD%E7%9A%84%E4%BB%BB%E5%8A%A1%E5%9C%A8%E6%AD%A4%E8%A7%A3%E5%86%BB%22%5D%0A%20%20T0%20--%3E%7C%22%E6%9C%9F%E9%99%90%E5%86%85%E8%80%97%E5%B0%BD%20runtime%22%7C%20THR%5B%22%E8%8A%82%E6%B5%81%EF%BC%9A%E8%AE%A9%E5%87%BA%20CPU%22%5D%0A%20%20THR%20--%3E%20TP%0A%20%20ADM%5B%22%E5%87%86%E5%85%A5%EF%BC%9A%CE%A3%20runtime%2Fperiod%20%E2%89%A4%200.95%22%5D%20--%3E%7C%22%E6%8B%92%E7%BB%9D%22%7C%20ERR%5B%22sched_setattr%20%E8%BF%94%E5%9B%9E%20EBUSY%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p>用户必须诚实申报；瞒报 runtime 会自己被节流。<span class="marginnote">初学者容易把 SCHED_DEADLINE 当成「更高级的 nice」，实际上 nice 只在 CFS 内部比权重、不承诺任何时刻表；DL 类给的是「每 period 给足 runtime」的硬合同——参数错导致被节流是合同在执行，不是内核出 bug。</span></p><p>实现上：runtime 用尽会节流到下周期，看起来像卡顿而不是降 nice。全局 EDF 在多核上要迁任务，亲和会破坏保证。用户必须用 SCHED_FLAG_RESET_ON_FORK 避免子进程继承。 读法上只引用<a href="/cs/heterogeneous-core-sched">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>SCHED_DEADLINE</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DL 服务器给 CFS 的全部。不保证与 cgroup cpu.max 的每一种组合直观。下一课把内核变成可抢占实时：PREEMPT_RT。</p><p>版本字段会变，课序钉的是机制对象「SCHED_DEADLINE」，不是某一主线内核的结构体名。 后课默认：CPU 可按 CBS 保证预算。完全抢占内核，下一课 PREEMPT_RT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SCHED_DEADLINE：CBS 预算 + EDF 选择 + 准入。</li><li>高于普通 CFS/RT 的一类（常规配置）。</li><li>PREEMPT_RT 是下一课。</li><li>出处：Linux sched-deadline；CBS 文献。</li></ul>',9))])}const T=o(A,[["render",c]]);export{S as __pageData,T as default};
